#!/bin/sh
# Xcode Cloud runs this right after cloning, before it opens the project.
# PeakPeek.xcodeproj is generated by XcodeGen from project.yml and is
# gitignored, so it has to be created here or the build has no project.
set -eu

if ! command -v xcodegen >/dev/null 2>&1; then
    brew install xcodegen
fi

cd "$CI_PRIMARY_REPOSITORY_PATH"
xcodegen generate
